import{_ as r,l as s,o as e,c as n,v as t,p as l,x as i,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"FAT 与目录项","description":"","frontmatter":{"title":"FAT 与目录项","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fat-filesystem.md","filePath":"cs/fat-filesystem.md","lastUpdated":1789023840000}'),A={name:"cs/fat-filesystem.md"};function T(f,a,h,F,m,u){const o=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="fat-与目录项" tabindex="-1">FAT 与目录项 <a class="header-anchor" href="#fat-与目录项" aria-label="Permalink to &quot;FAT 与目录项&quot;">​</a></h1><div class="epigraph"><p>文件分配表把簇号当成链表结点：目录项只记下起始簇，其余块号全在那张表里。</p><footer>—— 据 Microsoft FAT 规范；Arpaci-Dusseau, <em>OSTEP</em> 对 FAT 作为简单布局的整理</footer></div><p><a href="/cs/bootstrapping">上一课</a>把编译进阶收到自举链。操作系统主干已经有 <a href="/cs/vfs">VFS</a>、<a href="/cs/inode-dir">inode</a>、<a href="/cs/page-cache">页缓存</a> 与 <a href="/cs/ext4-journal">ext4 日志</a>。进阶课不从「什么是文件」重讲，缺口是<strong>盘上第一种可指着读的布局</strong>：FAT。后课默认已经读完本课的簇链与目录项。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Unix inode 把块指针放进对象本身；FAT 把几乎所有「下一簇」指针抽到卷头附近的一张表。目录项是定长记录：短名、属性、起始簇、文件大小。没有独立 inode 号，硬链接不是一等公民。缺口不是再写 <a href="/cs/file-bytestream">字节流</a>，而是：打开一个名字之后，内核如何只靠「起始簇 + FAT 数组」把逻辑偏移译成盘上簇。</p><p>本课不把 exFAT 的位图与目录哈希写成另一套百科。</p><p><span class="marginnote">FAT12/16/32 的差别主要是表项位宽与根目录是否也走簇链。教学对象是同一张表：空闲、坏簇、EOF、下一簇号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>卷：保留扇区（含 BPB）、FAT 的一份或两份副本、（FAT16 的）固定根目录区、数据区按簇编号。读文件：从目录项取首簇，沿 FAT 走到 EOF，中间簇按偏移取模。写：在 FAT 上找空闲项，链到尾，回写目录项的大小。删除：目录项标空闲，把簇链标空闲——回收与「名字消失」是两步，中间崩溃会泄漏簇。</p>',9)),(e(),l(p,null,{default:i(()=>[c(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIR%5B%22%E7%9B%AE%E5%BD%95%E9%A1%B9%3A%20%E5%90%8D%E4%B8%8E%E9%A6%96%E7%B0%87%22%5D%20--%3E%20FAT%5B%22FAT%20%E8%A1%A8%E9%A1%B9%22%5D%0A%20%20FAT%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E7%B0%87%E6%88%96%20EOF%22%5D%0A%20%20NEXT%20--%3E%20DATA%5B%22%E6%95%B0%E6%8D%AE%E7%B0%87%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>FAT 把元数据局部性做成「一张可缓存的数组」：簇分配不必扫整盘，但大文件的随机读要跳链，碎片使链变长。根目录在 FAT16 上是特殊文件，子目录只是属性为目录的普通簇链，里面仍是目录项。短名 8.3；长名靠 VFAT 槽拼出来，本课只承认它仍是目录项的编码，不是 inode。</p><p>对照主干：<a href="/cs/inode-dir">inode</a> 的直接/间接指针把「文件自己的块图」留在对象旁；FAT 把块图做成全局表。VFS 仍然看见 inode——Linux 给每个目录项造一个内存 inode，编号往往由簇号与槽位拼出来，盘上并没有 Unix inode 表。</p><p>不要把本课写成数据库栏的堆文件：这里没有元组，只有簇与目录记录。</p><p>实现上：簇大小一旦在格式化时钉死，小文件就会把整簇算进占用；这是 FAT 在闪存上仍然「看起来满」的来源。Linux vfat 用目录槽合成 inode 号，所以在同一目录里移动槽位会让号变，NFS 导出 FAT 因此发脆。 读法上只引用<a href="/cs/bootstrapping">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 布局与日志」课序里，对象是 <strong>FAT 与目录项</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>版本字段会变，课序钉的是机制对象「FAT 与目录项」，不是某一主线内核的结构体名。本课不引入块组、位图、extent。不保证 U 盘拔出等于干净卸载：FAT 常无日志，<code>fsck</code> 要扫表与目录。下一课用 ext2 说明另一条路：把空闲信息与 inode 表切成块组，而不是一张全局 FAT。</p><p>后课默认：簇链 + 目录项足以实现一种真实文件系统。块组如何切盘、位图如何代替 FAT 数组，下一课 ext2。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FAT 用全局表串簇；目录项只存名、属性、首簇与大小。</li><li>内存里仍可有 VFS inode，盘上没有 Unix inode 表。</li><li>块组与位图是下一课的缺口。</li><li>出处：Microsoft FAT Specification；Arpaci-Dusseau, <em>OSTEP</em>；McKusick 对 FFS 对照的背景。</li></ul>',12))])}const x=r(A,[["render",T]]);export{_ as __pageData,x as default};
